def root():
    for b in (Path.cwd().resolve(),Path(__file__).resolve().parent):
        for p in (b,*b.parents):
            if (p/"qseries_v2").is_dir(): return p
    raise RuntimeError("Q Series repository root not found")
def write(path,src):
    src=textwrap.dedent(src).lstrip(); ast.parse(src,filename=str(path))
    tmp=path.with_suffix(path.suffix+".tmp"); tmp.write_text(src,encoding="utf-8",newline="\n"); os.replace(tmp,path)
