        for name,src in MODULES.items(): write(pkg/name,src); print("[PASS] installed:",name)
        for name,src in TESTS.items(): write(r/name,src); print("[PASS] installed:",name)
        lines=[x for x in init.read_text(encoding="utf-8").splitlines() if "oad_173_crypto_condition_recent_history_exact_readback" not in x]
        for name in MODULES:
            exp="from ."+name[:-3]+" import *"
            if exp not in lines: lines.append(exp)
        write(init,"\n".join(x for x in lines if x.strip())+"\n")
        print("[PASS] OAD-172 preserved unchanged")
        print("[PASS] history retrieval now exact source-scoped; unrelated canonical rows cannot starve condition history")
